<script setup lang="ts">
/**
 * LoginForm (R4.1) — the redesigned sign-in card.
 *
 * Cinematic glass ticket-stub (AuthCard) with token-driven, accessible fields
 * (AuthField), inline validation, and a SINGLE top error banner on
 * failure (R13-15: the old design showed the same message twice — banner +
 * toast — so the toast is gone), and a config-driven `#oauth` slot. The auth
 * flow is unchanged: `useAuthStore.login` -> on success emit `success` + route
 * to the app home.
 */
import { computed, inject, ref, watch } from 'vue';
import { useRouter, useRoute } from 'vue-router';
import AuthCard from './auth/AuthCard.vue';
import AuthField from './auth/AuthField.vue';
import Button from './ui/Button.vue';
import Icon from './Icon.vue';
import { useAuthStore } from '../stores/useAuthStore';
import { useMessages } from '../composables/useMessages';
import { errorCodeMessage } from '../i18n/errors';
import { safeRedirect } from '../utils/safeRedirect';
import type { PhlixAppConfig } from '../app/types';

const emit = defineEmits<{ success: [] }>();

const auth = useAuthStore();
const router = useRouter();
const route = useRoute();
const { t } = useMessages();

const config = inject<PhlixAppConfig | null>('phlixConfig', null);
const homePath = computed(() => config?.home ?? config?.routerBase ?? '/app');
const signupPath = computed(() => `${config?.routerBase ?? '/app'}/signup`);

// Error-code doctrine (W4): the wire's stable `code` localizes through the
// contracts catalog for the configured locale; the server's English text is the
// LAST-resort fallback (kept for unknown codes / code-less failures), and the
// localized `auth.signInFailed` string covers the "nothing at all" case.
const errorMessage = computed(() =>
  errorCodeMessage(
    auth.errorCode,
    config?.locale,
    auth.error ?? t('auth.signInFailed'),
  ),
);

// The identifier may be a username OR an email — the store sends it under both
// keys and the back ends resolve either, so there's no email-format gate here.
const identifier = ref('');
const password = ref('');
const identifierError = ref<string | null>(null);
const passwordError = ref<string | null>(null);

// R13-15: the inline banner is the ONLY failure surface. It gates on a
// local flag (not `auth.error`) so a code-less failure that leaves the store
// silent still renders the generic localized message from `errorMessage`.
const submitFailed = ref(false);

function validate(): boolean {
  identifierError.value = !identifier.value.trim() ? t('auth.identifierRequired') : null;
  passwordError.value = !password.value ? t('auth.passwordRequired') : null;
  return !identifierError.value && !passwordError.value;
}

// CU-111 — an inline error that lingers after the fix reads as a lie: editing a
// field clears its own message. validate() re-derives both on the next submit.
watch(identifier, () => { identifierError.value = null; });
watch(password, () => { passwordError.value = null; });

async function handleSubmit(): Promise<void> {
  if (!validate()) return;
  submitFailed.value = false;
  const ok = await auth.login(identifier.value.trim(), password.value);
  if (ok) {
    emit('success');
    // Honor an internal `?redirect=` hop (e.g. the public invite-accept flow) but
    // ONLY when it is a safe path under the CONFIGURED SPA root — never an
    // absolute or protocol-relative URL (open-redirect guard). CU-112: the base
    // comes from config, it is not a hardcoded '/app'. Otherwise land on home.
    const redirect = safeRedirect(route.query.redirect, config?.routerBase ?? '/app');
    if (redirect) {
      void router.replace(redirect);
    } else {
      void router.push(homePath.value);
    }
  } else {
    submitFailed.value = true;
  }
}
</script>

<template>
  <AuthCard :eyebrow="t('auth.loginEyebrow')" :title="t('auth.loginTitle')" :subtitle="t('auth.loginSubtitle')">
    <p v-if="submitFailed" class="login__banner" role="alert">
      <Icon name="alert" class="login__banner-icon" />
      <span>{{ errorMessage }}</span>
    </p>

    <form class="login__form" novalidate @submit.prevent="handleSubmit">
      <AuthField
        v-model="identifier"
        name="identifier"
        :label="t('auth.usernameOrEmail')"
        type="text"
        autocomplete="username"
        :placeholder="t('auth.usernameOrEmailPlaceholder')"
        :error="identifierError"
        required
      />
      <AuthField
        v-model="password"
        :label="t('auth.password')"
        type="password"
        autocomplete="current-password"
        :placeholder="t('auth.passwordPlaceholder')"
        :error="passwordError"
        required
      />

      <Button type="submit" variant="solid" size="lg" block :loading="auth.loading">
        {{ auth.loading ? t('auth.signingIn') : t('auth.signIn') }}
      </Button>

      <template v-if="$slots.oauth">
        <div class="login__divider">{{ t('auth.orContinueWith') }}</div>
        <div class="login__oauth"><slot name="oauth" /></div>
      </template>
    </form>

    <template #footer>
      {{ t('auth.loginFooterPrompt') }}
      <RouterLink :to="signupPath" class="login__link">{{ t('auth.signupLink') }}</RouterLink>
      <!-- CU-094 (review ui__enduser): a locked-out visitor's only offered next
           step used to be creating a SECOND account. Self-service password
           reset does not exist estate-wide (reset is admin-only — the server's
           admin users API), so the honest path is stated plainly rather than a
           dead link being faked. -->
      <p class="login__hint">{{ t('auth.passwordRecoveryHint') }}</p>
    </template>
  </AuthCard>
</template>

